// Collect all news sources for reference database
const uaeNews = $('Merge UAE News').item?.json?.uae_news || [];
const gccNews = $('Merge GCC News').item?.json?.gcc_news || [];
const intlNews = $('Merge International News').item?.json?.international_news || [];
const euroNews = $('Merge International News').item?.json?.european_news || [];
const ameriNews = $('Merge International News').item?.json?.american_news || [];
const orgUpdates = $('Merge Org Updates').item?.json || {};

const references = [];

// Process UAE news
uaeNews.forEach(news => {
  if (news.link) {
    references.push({
      title: news.title,
      url: news.link,
      source_type: 'news',
      source_name: news.source,
      publication_date: new Date().toISOString().split('T')[0],
      crime_type: ['other'],
      region: ['UAE'],
      geographical_scope: 'local'
    });
  }
});

// Process GCC news
gccNews.forEach(news => {
  if (news.link) {
    references.push({
      title: news.title,
      url: news.link,
      source_type: 'news',
      source_name: news.source,
      publication_date: new Date().toISOString().split('T')[0],
      crime_type: ['other'],
      region: ['GCC'],
      geographical_scope: 'regional'
    });
  }
});

// Process international news
[...intlNews, ...euroNews, ...ameriNews].forEach(news => {
  if (news.link) {
    references.push({
      title: news.title,
      url: news.link,
      source_type: 'news',
      source_name: news.source,
      publication_date: new Date().toISOString().split('T')[0],
      crime_type: ['other'],
      region: ['Global'],
      geographical_scope: 'international'
    });
  }
});

// Process org updates
['unodc_updates', 'interpol_updates', 'europol_updates', 'fbi_updates'].forEach(key => {
  const updates = orgUpdates[key] || [];
  updates.forEach(update => {
    if (update.link) {
      references.push({
        title: update.title,
        url: update.link,
        source_type: 'international_org',
        source_name: key.replace('_updates', '').toUpperCase(),
        publication_date: new Date().toISOString().split('T')[0],
        crime_type: ['other'],
        region: ['Global'],
        geographical_scope: 'international'
      });
    }
  });
});

return {
  json: {
    operation: 'ADD_BATCH_REFERENCES',
    references: references.slice(0, 50) // Limit to 50 references per day
  }
};

// Generate the complete Arabic report
const dateVars = $('Set Date Variables').item.json;
const uaeAnalysis = $('Perplexity - UAE Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const gccAnalysis = $('Perplexity - GCC Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const intlAnalysis = $('Perplexity - International Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const orgAnalysis = $('Perplexity - Org Updates Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const patternAnalysis = $('Perplexity - Pattern Analysis').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';
const executiveSummary = $('Perplexity - Executive Summary').item?.json?.choices?.[0]?.message?.content || 'لا تتوفر بيانات';

// Collect citations from Perplexity responses
const uaeCitations = $('Perplexity - UAE Analysis').item?.json?.citations || [];
const gccCitations = $('Perplexity - GCC Analysis').item?.json?.citations || [];
const intlCitations = $('Perplexity - International Analysis').item?.json?.citations || [];
const orgCitations = $('Perplexity - Org Updates Analysis').item?.json?.citations || [];

const allCitations = [...new Set([...uaeCitations, ...gccCitations, ...intlCitations, ...orgCitations])];

// Format references
let referencesSection = '';
allCitations.forEach((cite, i) => {
  referencesSection += `${i + 1}. ${cite}\n`;
});

if (!referencesSection) {
  referencesSection = 'المراجع متوفرة في نظام قاعدة البيانات المرجعية';
}

const report = `
═══════════════════════════════════════════════════════════════
التقرير اليومي للرصد الجنائي والأمني
───────────────────────────────────────────────────────────────
التاريخ: ${dateVars.date_arabic}
وقت الإصدار: ٠٧:٠٠ صباحاً بتوقيت الإمارات
═══════════════════════════════════════════════════════════════

المحتويات:
─────────
١. ملخص تنفيذي
٢. الأنماط الجنائية المتكررة
٣. النشرة الإخبارية المحلية (الإمارات)
٤. النشرة الإخبارية الإقليمية (دول مجلس التعاون)
٥. النشرة الإخبارية الدولية
٦. تحديثات المنظمات الدولية
٧. المراجع والمصادر

═══════════════════════════════════════════════════════════════
١. الملخص التنفيذي
═══════════════════════════════════════════════════════════════
${executiveSummary}

═══════════════════════════════════════════════════════════════
٢. الأنماط الجنائية المتكررة
═══════════════════════════════════════════════════════════════
${patternAnalysis}

═══════════════════════════════════════════════════════════════
٣. النشرة الإخبارية المحلية (الإمارات العربية المتحدة)
═══════════════════════════════════════════════════════════════
${uaeAnalysis}

═══════════════════════════════════════════════════════════════
٤. النشرة الإخبارية الإقليمية (دول مجلس التعاون الخليجي)
═══════════════════════════════════════════════════════════════
${gccAnalysis}

═══════════════════════════════════════════════════════════════
٥. النشرة الإخبارية الدولية
═══════════════════════════════════════════════════════════════
${intlAnalysis}

═══════════════════════════════════════════════════════════════
٦. تحديثات المنظمات الدولية
═══════════════════════════════════════════════════════════════
${orgAnalysis}

═══════════════════════════════════════════════════════════════
٧. المراجع والمصادر
═══════════════════════════════════════════════════════════════
${referencesSection}

───────────────────────────────────────────────────────────────
نهاية التقرير
تم إعداد هذا التقرير آلياً بواسطة نظام الرصد الجنائي
───────────────────────────────────────────────────────────────
`;

return {
  json: {
    report_content: report,
    report_title: dateVars.report_title,
    file_name: dateVars.file_name,
    date: dateVars.date_english
  }
};

// Create Word document content
